CREATE OR REPLACE FUNCTION miglab.fn_claim_balance ( p_claim_id claim.claim_id%TYPE) RETURNS numeric AS $body$
DECLARE

 l_balance decimal(14,2);

BEGIN
 SELECT coalesce(total_billed,0)-coalesce(total_allowed,0)
 INTO STRICT l_balance FROM claim WHERE claim_id=p_claim_id;
 RETURN l_balance;
EXCEPTION WHEN no_data_found THEN RETURN NULL;
END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
